    "masonry" to "import dev.kindling.core.components.ui.masonry.KMasonryGrid\nimport dev.kindling.core.components.ui.masonry.KMasonryItem\n// (androidx.compose imports omitted)\n\n@Composable\nfun MasonryDemo() {\n    val items = remember {\n        listOf(\n            KMasonryItem(title = \"Fast\", text = \"Lightweight components.\"),\n            KMasonryItem(title = \"Themed\", text = \"Follows your color scheme and shapes across every card, with longer copy.\"),\n            KMasonryItem(text = \"Short note.\"),\n            KMasonryItem(title = \"Shortest column\", text = \"Cards fall into the shortest column.\"),\n            KMasonryItem(title = \"Multiplatform\", text = \"One codebase.\")\n        )\n    }\n    KMasonryGrid(\n        items = items,\n        modifier = Modifier.width(360.dp),\n        columns = 2,\n        gap = 8.dp,\n        cardPadding = 12.dp\n    )\n}\n",
    "pagination" to "import dev.kindling.core.components.ui.pagination.Pagination\nimport dev.kindling.core.components.ui.pagination.PaginationContent\nimport dev.kindling.core.components.ui.pagination.PaginationEllipsis\nimport dev.kindling.core.components.ui.pagination.PaginationItem\nimport dev.kindling.core.components.ui.pagination.PaginationLink\nimport dev.kindling.core.components.ui.pagination.PaginationNext\nimport dev.kindling.core.components.ui.pagination.PaginationPrevious\n// (androidx.compose imports omitted)\n\n@Composable\nfun PaginationDemo() {\n    var page by remember { mutableStateOf(2) }\n    val last = 3\n    Pagination {\n        PaginationContent {\n            PaginationItem { PaginationPrevious(onClick = { page = maxOf(1, page - 1) }, enabled = page > 1) }\n            (1..last).forEach { p ->\n                PaginationItem { PaginationLink(page = p, isActive = p == page, onClick = { page = p }) }\n            }\n            PaginationItem { PaginationEllipsis() }\n            PaginationItem { PaginationNext(onClick = { page = minOf(last, page + 1) }, enabled = page < last) }\n        }\n    }\n}\n",
    "picker" to "import dev.kindling.core.components.ui.picker.KRoulettePicker\n// (androidx.compose imports omitted)\n\n@Composable\nfun PickerDemo() {\n    val items = remember { listOf(\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\") }\n    var selected by remember { mutableIntStateOf(2) }\n    Column(\n        modifier = Modifier.width(200.dp),\n        horizontalAlignment = Alignment.CenterHorizontally,\n        verticalArrangement = Arrangement.spacedBy(8.dp)\n    ) {\n        KRoulettePicker(\n            items = items,\n            selectedIndex = selected,\n            onItemSelected = { selected = it },\n            visibleItemsCount = 5,\n            itemHeight = 36.dp\n        )\n        Text(\"Selected: \${items[selected]}\", color = MaterialTheme.colorScheme.onSurfaceVariant)\n    }\n}\n",
    "popover" to "import dev.kindling.core.components.ui.button.KButton\nimport dev.kindling.core.components.ui.button.KButtonVariant\nimport dev.kindling.core.components.ui.popover.KPopover\nimport dev.kindling.core.components.ui.popover.KPopoverAlign\nimport dev.kindling.core.components.ui.popover.KPopoverDescription\nimport dev.kindling.core.components.ui.popover.KPopoverHeader\nimport dev.kindling.core.components.ui.popover.KPopoverSide\nimport dev.kindling.core.components.ui.popover.KPopoverTitle\n// (androidx.compose imports omitted)\n\n@Composable\nfun PopoverDemo() {\n    var open by remember { mutableStateOf(false) }\n    Box(Modifier.fillMaxWidth().heightIn(min = 170.dp)) {\n        KPopover(\n            open = open,\n            onDismiss = { open = false },\n            side = KPopoverSide.Bottom,\n            align = KPopoverAlign.Start,\n            trigger = {\n                KButton(\n                    text = if (open) \"Close popover\" else \"Open popover\",\n                    onClick = { open = !open },\n                    variant = KButtonVariant.Outline\n                )\n            }\n        ) {\n            KPopoverHeader {\n                KPopoverTitle(\"Dimensions\")\n                KPopoverDescription(\"Set the dimensions for the layer.\")\n            }\n            Box(Modifier.width(220.dp))\n        }\n    }\n}\n",
    "questionnaire" to "import dev.kindling.core.components.ui.questionnaire.KQuestionnaire\nimport dev.kindling.core.components.ui.questionnaire.KQuestionnaireChoice\nimport dev.kindling.core.components.ui.questionnaire.KQuestionnaireChoiceType\nimport dev.kindling.core.components.ui.questionnaire.KQuestionnaireInput\n// (androidx.compose imports omitted)\n\n@Composable\nfun QuestionnaireDemo() {\n    var step by remember { mutableStateOf(0) }\n    var role by remember { mutableStateOf<String?>(null) }\n    var goal by remember { mutableStateOf(\"\") }\n    var done by remember { mutableStateOf(false) }\n    val roles = listOf(\"Designer\", \"Developer\", \"Other\")\n\n    Column(modifier = Modifier.width(380.dp)) {\n        if (done) {\n            Text(\"Thanks! Role: \${role ?: \"-\"}, goal: \$goal\", style = MaterialTheme.typography.bodyMedium)\n        } else if (step == 0) {\n            KQuestionnaire(\n                progressText = \"Question 1 of 2\",\n                title = \"What is your role?\",\n                content = {\n                    roles.forEach { r ->\n                        KQuestionnaireChoice(\n                            text = r,\n                            selected = role == r,\n                            onClick = { role = r },\n                            type = KQuestionnaireChoiceType.RADIO\n                        )\n                    }\n                },\n                onNext = { step = 1 },\n                canProceed = role != null\n            )\n        } else {\n            KQuestionnaire(\n                progressText = \"Question 2 of 2\",\n                title = \"What do you want to build?\",\n                content = {\n                    KQuestionnaireInput(value = goal, onValueChange = { goal = it })\n                },\n                onPrevious = { step = 0 },\n                onSubmit = { done = true },\n                isLastStep = true,\n                canProceed = goal.isNotBlank()\n            )\n        }\n    }\n}\n",
    "skeleton" to "import dev.kindling.core.components.ui.KSkeleton\n// (androidx.compose imports omitted)\n\n@Composable\nfun SkeletonDemo() {\n    Row(horizontalArrangement = Arrangement.spacedBy(16.dp), verticalAlignment = Alignment.CenterVertically) {\n        KSkeleton(Modifier.size(48.dp).clip(CircleShape))\n        Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {\n            KSkeleton(Modifier.height(16.dp).width(250.dp))\n            KSkeleton(Modifier.height(16.dp).width(200.dp))\n        }\n    }\n}\n",
    "spinner" to "import dev.kindling.core.components.ui.spinner.KSpinner\nimport dev.kindling.core.components.ui.spinner.KSpinnerSize\n// (androidx.compose imports omitted)\n\n@Composable\nfun SpinnerDemo() {\n    Row(horizontalArrangement = Arrangement.spacedBy(20.dp), verticalAlignment = Alignment.CenterVertically) {\n        KSpinner(size = KSpinnerSize.Sm)\n        KSpinner()\n        KSpinner(size = KSpinnerSize.Lg)\n        KSpinner(size = KSpinnerSize.Xl)\n    }\n}\n",
    "stepper" to "import dev.kindling.core.components.ui.button.KButton\nimport dev.kindling.core.components.ui.button.KButtonVariant\nimport dev.kindling.core.components.ui.stepper.KStepper\nimport dev.kindling.core.components.ui.stepper.KStepperContent\nimport dev.kindling.core.components.ui.stepper.KStepperIndicator\nimport dev.kindling.core.components.ui.stepper.KStepperItem\nimport dev.kindling.core.components.ui.stepper.KStepperList\nimport dev.kindling.core.components.ui.stepper.KStepperNext\nimport dev.kindling.core.components.ui.stepper.KStepperPrev\nimport dev.kindling.core.components.ui.stepper.KStepperSeparator\nimport dev.kindling.core.components.ui.stepper.KStepperTrigger\nimport dev.kindling.core.components.ui.stepper.rememberKStepperState\n// (androidx.compose imports omitted)\n\n@Composable\nfun StepperDemo() {\n    val steps = listOf(\"step-1\", \"step-2\", \"step-3\")\n    val state = rememberKStepperState(steps = steps)\n    Column(modifier = Modifier.width(360.dp)) {\n        KStepper(state = state) {\n            KStepperList {\n                steps.forEach { step ->\n                    KStepperItem(value = step) {\n                        KStepperTrigger { KStepperIndicator() }\n                        KStepperSeparator()\n                    }\n                }\n            }\n            KStepperContent(value = \"step-1\") { Text(\"Step 1: create your account.\") }\n            KStepperContent(value = \"step-2\") { Text(\"Step 2: add billing details.\") }\n            KStepperContent(value = \"step-3\") { Text(\"Step 3: review and confirm.\") }\n            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                KStepperPrev { onClick ->\n                    KButton(\n                        text = \"Back\",\n                        onClick = onClick,\n                        variant = KButtonVariant.Outline,\n                        enabled = state.canGoPrev\n                    )\n                }\n                KStepperNext { onClick ->\n                    KButton(text = \"Next\", onClick = onClick, enabled = state.canGoNext)\n                }\n            }\n        }\n    }\n}\n",
    "textarea" to "import dev.kindling.core.components.ui.KLabel\nimport dev.kindling.core.components.ui.KTextarea\n// (androidx.compose imports omitted)\n\n@Composable\nfun TextareaDemo() {\n    var message by remember { mutableStateOf(\"\") }\n    Column(modifier = Modifier.width(320.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {\n        KLabel(text = \"Your message\")\n        KTextarea(value = message, onValueChange = { message = it }, placeholder = \"Type your message here.\", minLines = 4)\n    }\n}\n",
    "toast" to "import dev.kindling.core.components.ui.button.KButton\nimport dev.kindling.core.components.ui.button.KButtonSize\nimport dev.kindling.core.components.ui.button.KButtonVariant\nimport dev.kindling.core.components.ui.toast.KToastManager\nimport dev.kindling.core.components.ui.toast.KToaster\n// (androidx.compose imports omitted)\n\n@Composable\nfun ToastDemo() {\n    Box(\n        modifier = Modifier\n            .fillMaxWidth()\n            .height(220.dp)\n            .clip(RoundedCornerShape(8.dp))\n    ) {\n        Column(\n            modifier = Modifier.fillMaxWidth().padding(4.dp),\n            verticalArrangement = Arrangement.spacedBy(8.dp)\n        ) {\n            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                KButton(\n                    text = \"Default\",\n                    onClick = { KToastManager.show(\"Event created\", \"Friday at 5:00 PM\") },\n                    variant = KButtonVariant.Outline,\n                    size = KButtonSize.Sm\n                )\n                KButton(\n                    text = \"Success\",\n                    onClick = { KToastManager.success(\"Saved\", \"Your changes were saved.\") },\n                    variant = KButtonVariant.Outline,\n                    size = KButtonSize.Sm\n                )\n            }\n            Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {\n                KButton(\n                    text = \"Error\",\n                    onClick = { KToastManager.error(\"Upload failed\", \"Please try again.\") },\n                    variant = KButtonVariant.Outline,\n                    size = KButtonSize.Sm\n                )\n                KButton(\n                    text = \"Action\",\n                    onClick = {\n                        KToastManager.show(\n                            message = \"File deleted\",\n                            actionLabel = \"Undo\",\n                            onAction = { KToastManager.info(\"Restored\") }\n                        )\n                    },\n                    variant = KButtonVariant.Outline,\n                    size = KButtonSize.Sm\n                )\n            }\n        }\n        KToaster(maxVisible = 2)\n    }\n}\n",
    "upload" to "import dev.kindling.core.components.ui.upload.KUploadArea\nimport dev.kindling.core.components.ui.upload.KUploadFile\nimport dev.kindling.core.components.ui.upload.KUploadStatus\n// (androidx.compose imports omitted)\n\n@Composable\nfun UploadDemo() {\n    var files by remember { mutableStateOf(listOf<KUploadFile>()) }\n    var counter by remember { mutableStateOf(0) }\n\n    LaunchedEffect(Unit) {\n        while (true) {\n            delay(250)\n            if (files.any { it.status == KUploadStatus.Uploading }) {\n                files = files.map { f ->\n                    if (f.status == KUploadStatus.Uploading) {\n                        val p = f.progress + 0.2f\n                        if (p >= 1f) f.copy(progress = 1f, status = KUploadStatus.Success)\n                        else f.copy(progress = p)\n                    } else f\n                }\n            }\n        }\n    }\n\n    KUploadArea(\n        files = files,\n        onSelectFiles = {\n            counter++\n            files = files + KUploadFile(\n                id = \"file-\$counter\",\n                name = \"photo-\$counter.png\",\n                sizeBytes = 240_000L + counter * 1_000L,\n                mimeType = \"image/png\",\n                status = KUploadStatus.Uploading,\n                progress = 0f\n            )\n        },\n        onRemoveFile = { f -> files = files.filter { it.id != f.id } },\n        acceptedTypesText = \"Simulated: each click adds a fake PNG\"\n    )\n}\n",
)
